import fs from "node:fs";
import pc from "picocolors";
import ora, { Ora } from "ora";
import { TurnResult, summarizeTurn } from "./core/turn.js";
import { highlightDiff, highlightCode } from "./syntax.js";
import { InformationFlowBoundary } from "./core/egress.js";
import { visibleControls } from "./file_diff.js";
import { isNexusDirPermissive } from "./core/durable_file.js";
import { redactDiagnosticForOutput } from "./core/persistence_protection.js";

export function redactSecrets(text: string): string {
  if (!text) return text;
  let result = text;
  try {
    const boundary = InformationFlowBoundary.getGlobalInstance();
    const redacted = boundary.redactForTelemetry(text);
    if (typeof redacted === "string") {
      result = redacted;
    }
  } catch {}
  return redactSecretPatterns(result);
}

interface RedactionRule { name: string; scope: "all" | "multiline"; pattern: string; flags: string; replacement: string }

let redactionRules: Array<{ regex: RegExp; replacement: string }> | undefined;

/** The shared pattern table (redaction_patterns.json), compiled once: the single source for these literal patterns, also mirrored in Rust. */
function rules(): Array<{ regex: RegExp; replacement: string }> {
  if (!redactionRules) {
    const table = JSON.parse(fs.readFileSync(new URL("./redaction_patterns.json", import.meta.url), "utf8")) as { rules: RedactionRule[] };
    redactionRules = table.rules.map((r) => ({ regex: new RegExp(r.pattern, `${r.flags}g`), replacement: r.replacement }));
  }
  return redactionRules;
}

/** The literal-pattern half of redactSecrets (no classifier call): for text the classifier has already been run over. */
export function redactSecretPatterns(result: string): string {
  let out = result;
  for (const { regex, replacement } of rules()) out = out.replace(regex, replacement);
  return out;
}

/** Text safe to write to a terminal: secrets redacted, then every terminal control/bidi character made visible. */
export function safeTerminal(text: string): string {
  return visibleControls(redactSecrets(text));
}

/** The one operator-facing diagnostic formatter: an Error or any value, redacted (fail-closed) and made terminal-safe. */
export function formatDiagnosticForOutput(error: unknown): string {
  const message = error instanceof Error ? error.message : String(error);
  return safeTerminal(redactDiagnosticForOutput(message));
}

export class TerminalUI {
  private spinner: Ora | null = null;

  banner(): void {
    console.log(`\n${pc.bold(pc.black(pc.bgCyan(" NEXUS ")))} ${pc.dim("local engineering agent")}`);
    console.log(pc.dim("Understand the work. Inspect the evidence. Keep the decision yours.\n"));
  startedAt: number;
  durationMs: number | null;
  /** Unified diff of the file change this call made (redacted, capped at MAX_DIFF_DETAIL). */
  diff?: string;
  /** Characters in the complete (redacted) diff, before the cap. */
  diffChars?: number;
  /** Where the complete diff was written, when it was. */
  diffPath?: string;
}

/**
 * Pretty JSON with each string value redacted before encoding: quoting turns `KEY="value"` into `KEY=\"value\"`
 * and escapes into literal `\u001b`, both of which a pass over the encoded text misses.
 */
export function redactedJson(value: unknown): string {
  const json = JSON.stringify(value ?? {}, (_key, v) => (typeof v === "string" ? redactPlain(v) : v), 2);
  return redactSecrets(json);
}

/** Tool output is usually JSON text; its string values are redacted before re-encoding, as with arguments. */
function redactedOutput(text: string): string {
  try {
    const parsed: unknown = JSON.parse(text);
    if (typeof parsed === "string" || (parsed !== null && typeof parsed === "object")) return redactedJson(parsed);
  } catch {
    // Plain text output.
  }
  return text;
}

/** A diff as it may be shown or stored: secrets redacted, then control characters made visible. */
export function safeDiffText(diff: string): string {
  return safeTerminal(diff);
}

