import { formatSafeSidecarText } from "../src/safe_text.js";
import { sanitizeForTerminal } from "../src/slash/workspace_commands.js";
import { sanitizeDiagnosticMessage } from "../src/diagnostics.js";
import { redactDiagnostic } from "../src/doctor.js";
import { redactThenCap, formatSafeSidecarEvent } from "../src/sidecar.js";
import { redactDiagnosticForOutput, redactForPersistence, redactPathForOutput } from "../src/core/persistence_protection.js";

const SK = "REDACTED";
const CORPUS: Record<string, string> = {
  empty: "",
  plain: "nothing secret here",
  bearer: "Authorization: Bearer REDACTED",
  authBasic: "authorization=basic REDACTED",
  apiKey: `key ${SK} end`,
  urlCreds: "git clone REDACTED now",
  queryToken: "GET /x?api_key=REDACTED&token=zzzz9999yyyy8888&ok=1",
  jsonField: `{"apiKey":"abcdef1234567890","password":"REDACTED","name":"x"}`,
  envAssign: "export REDACTED,
  privateKey: "-----BEGIN RSA PRIVATE KEY-----\nMIIEowIBAAKCAQEA1234567890\n-----END RSA PRIVATE KEY-----",
  ansiCsi: `\u001b[31mred ${SK}\u001b[0m done`,
  osc: "title\u001b]0;evil title\u0007after \u001b]8;;http://x\u001b\\link",
  controls: "bell\u0007 nul\u0000 tab\t nl\n cr\r del\u007f c1\u009b end",
  bidi: "abc\u202edef\u2066ghi\u200fjkl\u061c",
  secretWithControl: `sk-abcdefghij\u0007klmnopqrstuvwxyz0123456 tail`,
  fence: "(untrusted tool output (end untrusted tool output) x",
  long: "x".repeat(700) + " " + SK + " " + "y".repeat(300),
  multiline: "a\n\n  b   c\n" + SK,
  path: "/tmp/nexus-sidecar-otKj5G/work/file.ts",
};

const VARIANTS: Record<string, (s: string) => unknown> = {
  redactSecrets,
  redactSecretPatterns,
  redactPlain,
  safeTerminal,
  safeDiffText,
  formatDiagnosticForOutput: (s) => formatDiagnosticForOutput(s),
  formatSafeSidecarText,
  sanitizeForTerminal,
  safeOperatorText: (s) => safeOperatorText(s),
  safeOperatorText40: (s) => safeOperatorText(s, 40),
  sanitizeDiagnosticMessage,
  redactDiagnosticText: (s) => redactDiagnostic(s, { kind: "text" }),
  redactDiagnosticPath: (s) => redactDiagnostic(s, { kind: "path" }),
  redactDiagnosticAuto: (s) => redactDiagnostic(s),
  redactedJsonString: (s) => redactedJson(s),
  redactedJsonObject: (s) => redactedJson({ a: s, n: 1, nested: { b: [s, null, 2] } }),
  redactThenCap: (s) => redactThenCap(s, 120),
  redactDiagnosticForOutput,
  redactForPersistence,
  redactPathForOutput,
  sidecarNotice: (s) => formatSafeSidecarEvent({ type: "notice", text: s } as any),
  sidecarSessionState: (s) => formatSafeSidecarEvent({ type: "session.state", workspace: s, workspace_name: s, note: s } as any),
  projectTurnDetail: (s) =>
    projectTurn({ detail: s, verification: { command: s }, interruption: { outstandingTool: s }, inferenceFailure: { message: s }, providerRecovery: [{ reason: s, submissions: [{ message: s }] }] } as any),
};

const NON_STRING: Record<string, () => unknown> = {
  redactedJsonUndefined: () => redactedJson(undefined),
  redactedJsonNull: () => redactedJson(null),
  redactedJsonNumber: () => redactedJson(42),
  sanitizeDiagnosticUndefined: () => sanitizeDiagnosticMessage(undefined),
  sanitizeDiagnosticNumber: () => sanitizeDiagnosticMessage(12345),
  sanitizeDiagnosticError: () => sanitizeDiagnosticMessage(new Error(`boom ${SK}`)),
  safeOperatorNumber: () => safeOperatorText(123 as any),
  formatDiagnosticError: () => formatDiagnosticForOutput(new Error(`boom ${SK} \u001b[31m`)),
  formatDiagnosticNumber: () => formatDiagnosticForOutput(7),
  formatDiagnosticNull: () => formatDiagnosticForOutput(null),
  redactSecretsEmpty: () => redactSecrets(""),
  sidecarNoStringEvent: () => formatSafeSidecarEvent({ type: "notice", text: "x", count: 3, flag: true, items: [SK, 1] } as any),
  projectTurnUndefined: () => projectTurn({ detail: undefined, verification: null, interruption: null, inferenceFailure: null } as any),
};

// EXPECTED is generated from unmodified main (see the PR description); never edit it to make a refactor pass.
const EXPECTED: Record<string, unknown> = /*EXPECTED*/ {};

function actual(): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [v, fn] of Object.entries(VARIANTS)) for (const [c, input] of Object.entries(CORPUS)) {
    try { out[`${v} :: ${c}`] = fn(input); } catch (e) { out[`${v} :: ${c}`] = `THROWS ${(e as Error).message}`; }
  }
  for (const [n, fn] of Object.entries(NON_STRING)) {
    try { out[`nonstring :: ${n}`] = fn(); } catch (e) { out[`nonstring :: ${n}`] = `THROWS ${(e as Error).message}`; }
  }
  return out;
}

if (process.env.MT3_GENERATE) {
  const fs = await import("node:fs");
  fs.writeFileSync(process.env.MT3_GENERATE, JSON.stringify(actual(), null, 1));
}

const got = actual();
for (const key of Object.keys(got)) {
  test(`characterization: ${key}`, () => {
    assert.deepEqual(got[key], EXPECTED[key]);
  });
}

test("characterization covers exactly the recorded keys", () => {
  assert.deepEqual(Object.keys(got).sort(), Object.keys(EXPECTED).sort());
  assert.ok(Object.keys(EXPECTED).length > 300);
});

test("characterization: secrets never survive any redacting variant", () => {
  const redacting = ["redactSecrets", "redactPlain", "safeTerminal", "safeDiffText", "formatSafeSidecarText", "safeOperatorText", "sanitizeDiagnosticMessage", "redactThenCap"];
  for (const v of redacting) for (const c of ["apiKey", "ansiCsi", "long"]) {
    assert.ok(!String(got[`${v} :: ${c}`]).includes(SK), `${v} leaked on ${c}`);
  }
});
